function pair(a, t) {
  let i = 0, j = a.length - 1;
  while (i < j) {
    const s = a[i] + a[j];
    if (s === t) return [i, j];
    if (s < t) i++; else j--;
  }
  return null;
}
console.log(JSON.stringify(pair([1, 3, 4, 6, 9], 10)));

const memo = new Map();
function ways(n) {
  if (n <= 1) return 1;
  if (memo.has(n)) return memo.get(n);
  const r = ways(n - 1) + ways(n - 2);
  memo.set(n, r);
  return r;
}
console.log(ways(5));

function firstTrue(lo, hi, ok) {
  while (lo < hi) {
    const mid = Math.floor((lo + hi) / 2);
    if (ok(mid)) hi = mid;
    else lo = mid;
  }
  return lo;
}

